window.RP_SESSION={"id":"S-7dceaa5ec819","messages":[{"id":"RP-III-0130504","time":"2026-07-29T23:05:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130505","time":"2026-07-29T23:05:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130506","time":"2026-07-29T23:05:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130507","time":"2026-07-29T23:06:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"눈이 뻑뻑해질 정도로 지루한 서류 작업들이 끝나 의자에 앉은 채로 기지개를 켰다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130508","time":"2026-07-29T23:06:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"으~~!\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130509","time":"2026-07-29T23:07:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"내가 인수인계 받았어야 할 일인 줄 알고 열심히 하다보니 그저 짬 맞은 거란 걸 중간에 깨닫았다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130510","time":"2026-07-29T23:07:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"복수할테다 션.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130511","time":"2026-07-29T23:08:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"아직 펜대가 익숙치 않아서인지, 영지의 일이 겹쳐서인지는 모르겠는데 몇날며칠을 하루종일 집무실 의자에서 벗어날 수 없었다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130512","time":"2026-07-29T23:10:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"낭만이니 뭐니... 그냥 부려먹으려고 꼬셔먹은 거 같은데...\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130513","time":"2026-07-29T23:11:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"머리를 긁적이며 창문을 열고 션 형씨한테 받았던 담배 하나를 물었다.\n\n이거, 일 떠넘기려고 줬던 거구만...","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130514","time":"2026-07-29T23:12:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"어라?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130515","time":"2026-07-29T23:12:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"옆옆 창문에서 션도 고개를 빠꼼 내밀고 있었습니다. 역시나 가면을 조금 들어올린 채 궐련을 물고 있네요.\n\n\"뭐야, 공대장 취임 일주일도 안되어서 땡땡이신가?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130516","time":"2026-07-29T23:13:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"땡땡이는 무슨. 이제야 어느정도 정리 마치고 잠깐 바람 좀 쐤네.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130517","time":"2026-07-29T23:14:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"조심하시게. 가끔 그러고 있으면 델타인이 벽을 타거든.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130518","time":"2026-07-29T23:14:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그럼 뭐... 붙잡아다가 혼내야지. 알아먹을진 몰라도.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130519","time":"2026-07-29T23:15:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그보다 자네가 건네준 서류들 이거, 짬처리도 몇 개 섞여있지?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130520","time":"2026-07-29T23:16:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"이 사람이 큰일 날 소리를. 다 필요한 과정이야. 누가 휴가라도 나갈 때를 대비해 미리미리 작업 속도를 높여놔야지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130521","time":"2026-07-29T23:16:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"션뻔뻔.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130522","time":"2026-07-29T23:17:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"뻔뻔하기는... 영지 건 정리하느랴 짬 맞은 일 하랴 정신이 하나도 없었단 말일세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130523","time":"2026-07-29T23:17:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그보다... 저번에 혼내던 소리가 나던데 마리아 양과 가델랏 양, 형씨가 한소리 했나?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130524","time":"2026-07-29T23:18:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"영지 건은 자네의 일이니 응당 자네가 해야할 것이고, 자네가 '짬 맞은-'이라 표현한 일은 나도 스텔라에게 거친 과정이니 둘 다 적법한 자네의 일일세.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130525","time":"2026-07-29T23:18:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"오, 맞아. 방음이 잘 안되나? 난 조용조용 말했다고 생각했는데.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130526","time":"2026-07-29T23:19:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"신고식 겸 부조리란 소리군...\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130527","time":"2026-07-29T23:20:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"대충 웅얼거리는 목소리만 들렸네. 의뢰 보고서를 확인하니 그 두 사람일 거 같아서 말이야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130528","time":"2026-07-29T23:30:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"길거리에서 폭발을 일으켰다고… 뭐, 그것보다 더 중요한 건 자기네들 안위만 생각해서 의뢰인의 의뢰 대상 물품을 홀랑 주워와버렸단 거지만.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130529","time":"2026-07-29T23:31:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"뭣. 물품 경비 의뢰 아니였나? 그걸 가져왔다고.\"\n\n\"그런 건 안 쓰여있었는데.... 혼날 만했구만.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130530","time":"2026-07-29T23:32:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그래서 어찌했나? 돌려줬는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130531","time":"2026-07-29T23:33:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"추가로, 꽤 위험한 분위기가 느껴지는 물건인 걸 알았는데 그걸 안 알리고 길드 내부에 놔뒀더군….\"\n\n션이 말을 끊고 잠시 담배 연기를 허공으로 뱉었습니다.\n\n\"아직. 내 체질이 그런 걸 막곤 하니까 내가 보관하기로 했지. 그리고 그 두 사람이 의뢰인에게 사과하고 물건을 돌려주러 갈 때 와서 받으라고 해뒀네.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130532","time":"2026-07-29T23:37:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"마리아 양이 사고뭉치긴 해도 그런 걸 할 성정은 안될텐데...\"\n\n\"가델랏 양이군? 저번에 봤을 때 방정맞은 면모도 있는 거 같고... 팀워크나 단체생활도 좀 가르쳐야 할 것 같던데.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130533","time":"2026-07-29T23:37:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"그렇지? 마리아는 겁보니까.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130534","time":"2026-07-29T23:38:00+09:00","room":"RP III","name":"션 / 델타인","profile":"션","identity":"reviewed","type":"dialogue","body":"션이 창틀 아래로 고개를 쭉 내밀었습니다. 이내 아주 미미한 기운이 맴도는 담뱃재를 아래로 톡 털었습니다. 그리고…\n\n\"우왓, 뜨거! 방금 뭐지? 천벌인가?\"\n\n하는 델타인의 목소리가 들려왔습니다.","characters":["P-3bbc4a823df9","P-c93f55c91873"]},{"id":"RP-III-0130535","time":"2026-07-29T23:39:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n창 밖으로 머리를 더 빼어 아래를 내려보았습니다.\n\n\"호랑이도 제말하면 나온다더니.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130536","time":"2026-07-29T23:39:00+09:00","room":"RP III","name":"션 / 델타인","profile":"션","identity":"reviewed","type":"dialogue","body":"!체력","characters":["P-3bbc4a823df9","P-c93f55c91873"]},{"id":"RP-III-0130537","time":"2026-07-29T23:39:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 체력 판정 :\n[12] + [0] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0130538","time":"2026-07-29T23:39:00+09:00","room":"RP III","name":"션 / 델타인","profile":"션","identity":"reviewed","type":"dialogue","body":"다행히 땜빵은 안 생겼네요.","characters":["P-3bbc4a823df9","P-c93f55c91873"]},{"id":"RP-III-0130539","time":"2026-07-29T23:39:00+09:00","room":"RP III","name":"션 / 델타인","profile":"션","identity":"reviewed","type":"dialogue","body":"머리카락이 조금 탄 정도.","characters":["P-3bbc4a823df9","P-c93f55c91873"]},{"id":"RP-III-0130540","time":"2026-07-29T23:40:00+09:00","room":"RP III","name":"션 / 델타인","profile":"션","identity":"reviewed","type":"dialogue","body":"\"이야, 알브레히트 3세. 방금 봤지? 라운데라가 천벌을 내렸지만 이 어둠대왕께서는 고작 머리칼 한가닥 타고 만 거? 캬~\"\n\n하는 목소리에 뒤이어 쓱쓱싹싹 빗자루질 하며 길드 내부로 들어가는 델타인.","characters":["P-3bbc4a823df9","P-c93f55c91873"]},{"id":"RP-III-0130541","time":"2026-07-29T23:40:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"……저놈은 당췌 어찌 다뤄야할지 감도 안 잡히는구먼.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130542","time":"2026-07-29T23:40:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"....애는 참 밝아.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130543","time":"2026-07-29T23:41:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"큰 사고는 안 치니까 차라리 이정도로 내버려두는 게 낫겠지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130544","time":"2026-07-29T23:43:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"하긴 사고를 쳐봤자 자네만 하겠나.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130545","time":"2026-07-29T23:44:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"…라고 동쪽 성벽과 시가지를 날려먹은 사람이 말했다!","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130546","time":"2026-07-29T23:44:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"크흐흐... 내 사고는 제법 거하긴 했지.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130547","time":"2026-07-29T23:45:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"결과적으로... 잘 풀렸으니까 뭐... 그때 봤던 형씨 예전 동료들과는 계속 연락하는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130548","time":"2026-07-29T23:45:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"아니?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130549","time":"2026-07-29T23:45:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"때 되면 죽고, 연이 되면 다시 만나겠지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130550","time":"2026-07-29T23:48:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"것 참... 정이라곤 없는 사람일세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130551","time":"2026-07-29T23:49:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"사람은 저마다 각자의 길이 있는 거야. 얻고 싶어도 얻을 수 없고, 끊고 싶어도 끊어지지 않는 인연이 있는 거라네.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130552","time":"2026-07-29T23:49:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"뭐, 정 필요하면 그쪽에서 연락하겠지만.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130553","time":"2026-07-29T23:52:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그런가? 음... 아무래도 확실히.\"\n\n담배를 툭툭 털고는.\n\n\"형씨는 내가 공격대장이 된 것, 잘 된 일이라고 생각하나?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130554","time":"2026-07-29T23:52:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"글쎄? 두고 보면 알 일이지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130555","time":"2026-07-29T23:53:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"자네도 모험을 좋아하지 않는감?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130556","time":"2026-07-29T23:53:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"마음이 굴하지 않는다면 아무리 먼 곳이라도 갈 수 있다고.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130557","time":"2026-07-29T23:54:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"그렇지. 좋아하지.\"\n\n\"일단은 펜을 잡은 손이 좀 빨라져야 모험할 시간이 나겠지만 말이야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130558","time":"2026-07-29T23:55:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"것 보라니까.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130559","time":"2026-07-29T23:55:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"짬 때리… 아니, 다양한 업무 적응 기간은 필요해.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130560","time":"2026-07-29T23:56:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"이 사람아.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130561","time":"2026-07-29T23:57:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"으휴... 열심히 해야지. 언제까지고 빈 자리일 수도 없었으니....\"\n\n\"실은 안하려고 했는데, 나말고 할 사람도 없더라고.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130562","time":"2026-07-29T23:58:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"어, 뭐. 나는 존 군이 세상 경험 좀 더 하면 적격이지 않나 싶은데.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130563","time":"2026-07-29T23:59:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"존 형씨 나쁘지 않지. 상냥하기도 하고, 상황을 볼 줄도 알고 말일세.\"\n\n\"둘 중 누구 하나 죽으면 생각해볼만하군.\"\n\n킬킬 웃었습니다.","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130564","time":"2026-07-30T00:00:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"단순 행정 업무만이라면 에일린 양도 괜찮겠군.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130565","time":"2026-07-30T00:02:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"짬처리 할 생각만 가득하군.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130566","time":"2026-07-30T00:03:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"바키르 경 소식은 좀 들었는가?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130567","time":"2026-07-30T00:04:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"오, 잊고 있었군. 같이 차를 마시긴 했었는데….\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130568","time":"2026-07-30T00:06:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"사자회 소식을 듣자하니 바쁘다 못해 정신이 하나도 없을 것 같은데.\"\n\n\"헬리오스 형씨도 사자회로 갔었지?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130569","time":"2026-07-30T00:07:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"자꾸 나한테 사내 자식들 소식 좀 묻지 말게.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130570","time":"2026-07-30T00:07:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"그거 알아서 뭐하게?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130571","time":"2026-07-30T00:08:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"으이구. 한결 같기는...\"\n\n\"내가 여자들 소식은 물어서 뭐하나?\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130572","time":"2026-07-30T00:10:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"그래야 다른 인연을 쫄래쫄래 쫓아가지.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130573","time":"2026-07-30T00:10:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"그리고, 남자는 가만 냅두면 알아서 회복하는 생물이야.\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130574","time":"2026-07-30T00:12:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"에잇. 다른 인연은 무슨.\"\n\n\"나는 징그러운 남정네들이랑 술이나 한 잔씩 기울여야지...\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130575","time":"2026-07-30T00:13:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"오……. 그런 취향이었군…….\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130576","time":"2026-07-30T00:13:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"나는 응원하네. 헌데 꼭 남자 좋아하는 남자 놈들은 길드에서 사라진단 말이야?\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130577","time":"2026-07-30T00:14:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"이 사람아. 누가 들으면 진짠 줄 알아.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130578","time":"2026-07-30T00:15:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"\"얼레, 아쉬운 일이군. 경쟁자가 하나 줄어드는 건데….\"\n\n이어서 창문 안쪽에서 두런두런 말 소리가 들려왔습니다.\n\n\"어, 아니, 마리. 그런 이야기가 아니고…. 으악! 정말 아냐!\"","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130579","time":"2026-07-30T00:15:00+09:00","room":"RP III","name":"션","profile":"션","identity":"reviewed","type":"dialogue","body":"별안간 션이 창문 안으로 홱 들어가버렸습니다.","characters":["P-3bbc4a823df9"]},{"id":"RP-III-0130580","time":"2026-07-30T00:16:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"어이쿠. 매를 버는구만. 나는 모르는 일일세.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130581","time":"2026-07-30T00:17:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"\"뭐... 고마운 일도 있으니 다음에 술 한잔 사지.\"\n\n떠나간 션쪽 창문을 바라보며 나지막히 말했습니다.\n\n\"다음에 말이야.\"","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130582","time":"2026-07-30T00:17:00+09:00","room":"RP III","name":"토르번 팔켄하인","profile":"토르번 팔켄하인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-7ba611cf90be"]},{"id":"RP-III-0130583","time":"2026-07-30T00:17:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
